/* Screenshot-by-screenshot SaveTrip Accounts UI — v10.
   Additive frontend; uses existing authenticated API; no fabricated accounting or GPS records. */
(function(){
'use strict';
if (!window.G?.screens?.accounts || G.__accountsV10) return;
G.__accountsV10=true;
const previous=G.screens.accounts;
const e=x=>esc(x??'');
const a=x=>Array.isArray(x)?x:[];
const n=x=>Number(x)||0;
const money=x=>x===null||x===undefined||x===''?'—':inr(x,0);
const fmoney=x=>x===null||x===undefined||x===''?'—':inr(x,2);
const numeric=x=>x===null||x===undefined?'—':num(x);
const percent=x=>x===null||x===undefined?'—':`${Number(x).toFixed(1)}%`;
const val=x=>x===null||x===undefined||x===''?'—':Array.isArray(x)?x.map(y=>typeof y==='object'?(y.name||y.role||JSON.stringify(y)):String(y)).join(', '):typeof x==='object'?JSON.stringify(x):e(x);
const iconPaths={sales:'<path d="M4 20V12m5 8V4m5 16v-8m5 8V8"/>',transactions:'<path d="m6 4 0 16m-3-3 3 3 3-3M18 20V4m-3 3 3-3 3 3"/>',receivables:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M3 10h18M16 14h3"/>',reports:'<path d="M5 3h10l5 5v13H5zM15 3v5h5M8 12h8M8 16h6"/>',invoices:'<path d="M6 2h12v20l-3-2-3 2-3-2-3 2zM9 8h6m-6 4h6m-6 4h4"/>',reconciliation:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',agent:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-3a6 6 0 0 1 12 0v3M17 8h5m-2.5-2.5v5"/>',loyalty:'<path d="M4 11v11h16V11M2 7h20v4H2zM12 7v15M8 7C2 7 3 1 7 2c3 1 5 5 5 5s2-4 5-5c4-1 5 5-1 5"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="3"/><path d="M7 2v4m10-4v4M3 10h18"/>',print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3M6 15h12v7H6z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M5 19v3h14v-3"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.7 10.7 6.6-4.2m-6.6 8.9 6.6 3.9"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',chevron:'<path d="m6 9 6 6 6-6"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',back:'<path d="m14 6-6 6 6 6"/>',credit:'<path d="m12 3 0 18m-6-6 6 6 6-6"/>',debit:'<path d="m12 21 0-18m-6 6 6-6 6 6"/>',filter:'<path d="M4 7h16M7 12h10m-7 5h4"/>',edit:'<path d="m15 4 5 5M4 20l5-1L20 8a3 3 0 0 0-4-4L5 15z"/>',trash:'<path d="M4 7h16m-12 0-1 14h10L16 7m-6 4v6m4-6v6M9 7V4h6v3"/>',plus:'<path d="M12 4v16M4 12h16"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7Z"/><circle cx="12" cy="12" r="3"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',bus:'<rect x="3" y="3" width="18" height="16" rx="3"/><path d="M3 11h18m-13 8v2m8-2v2"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',sparkle:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const ic=(k,s=17)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.9">${iconPaths[k]||iconPaths.reports}</svg>`;
const navs=[['analytics','Sales','sales','accounts.view'],['transactions','Transactions','transactions','accounts.view'],['receivables','Receivables','receivables','accounts.ledger'],['reports','Reports','reports','accounts.reports'],['invoices','Invoices','invoices','accounts.view'],['reconciliation','OTA Invoice Verifier','reconciliation','accounts.reconciliation'],['agent-settings','Agent Settings','agent','accounts.view'],['coupons','Loyalty','loyalty','offers.manage_coupons']];
const cat=[['FLEET','fleet-operations','Fleet Operations','Utilization, mileage and driver allocation together per bus, per driver, per day and per trip.','bus'],['CREW','driver-behavior','Driver Behaviour','Driving score per driver, worst first: hard brakes, harsh acceleration, over-speed, idling and free run.','transactions'],['CREW','staff-duty','Staff Duty Statement','One driver / staff member every trip with date, bus, route, duty and Daily Ops details.','user'],['BOOKINGS','point-usage','Boarding & Dropping Points','Which boarding and dropping points were used, how often: bookings, seats, share and days used.','location'],['BOOKINGS','metro-bookings','Metro Bookings','Every PNR with a Metro pickup or drop, its metro fare and booking revenue — pick Pickup, Drop or both.','bus'],['BOOKINGS','van-bookings','Pickup Van Bookings','Every PNR with a Pickup Van pickup or drop and its booking revenue — pick Pickup, Drop or both.','bus'],['BOOKINGS','point-performance','Point Performance','Any one pickup or drop point: PNRs, seats, revenue, share and rank by service, weekday and trip.','location'],['BOOKINGS','station-performance','Station Performance','City-to-city sales by station pair, boarding and dropping station, schedule and day.','bus'],['BOOKINGS','no-shows','No-shows','Every no-show seat: passenger, trip, fare — whether the seat was resold on that trip and the recovered fare.','user'],['BOOKINGS','cancellations','Cancellations','Every cancelled booking: amount, charge kept, who cancelled — seats resold on that trip and refund.','transactions'],['CUSTOMERS','frequent-travellers','Frequent Travellers','Who travels with you most: trips, spend, channels and last trip per passenger.','user'],['FINANCE','trip-pnl','Trip P&L / Occupancy','Per trip: seats sold vs capacity, occupancy, net sales, expenses and profit.','sales'],['FINANCE','expenses','Expenses','Category-wise expenses for the period: each category’s total and share, then by bus and trip.','receivables']];
const dateDefault=()=>({from:G.query().from||addDays(today(),-6),to:G.query().to||today()});
const grouped=(rows,key)=>Object.groupBy?Object.groupBy(rows,key):rows.reduce((b,r)=>{const k=key(r);(b[k]||=[]).push(r);return b},{});
const sum=(rows,k)=>a(rows).reduce((v,r)=>v+n(r[k]),0);
const btn=(text,action,cl='',attr='')=>`<button type="button" class="ac10-btn ${cl}" data-ac10="${action}" ${attr}>${text}</button>`;
const stat=(label,value,kind='',ex='')=>`<div class="ac10-stat ${kind}"><span>${e(label)}</span><strong>${value}</strong>${ex?`<small>${ex}</small>`:''}</div>`;
const empty=(txt='No data for this period')=>`<div class="ac10-empty">${ic('reports',28)}<span>${e(txt)}</span></div>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="ac10-field"><span>${e(label)}</span><input name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></label>`;
const options=(vals,cur)=>vals.map(x=>{const [k,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(k)}" ${String(k)===String(cur)?'selected':''}>${e(l)}</option>`}).join('');
const sel=(name,opts,cur,cl='')=>`<label class="ac10-select ${cl}"><select name="${e(name)}">${options(opts,cur)}</select>${ic('chevron',16)}</label>`;
const dateInput=(name,v)=>`<label class="ac10-date"><span>${ic('calendar',21)}</span><input type="date" name="${name}" value="${e(v)}" aria-label="${name==='from'?'From':'To'} date"></label>`;
const fmt=(v,t)=>t==='money'?money(v):t==='decimalMoney'?fmoney(v):t==='pct'?percent(v):t==='date'?fdate(v):t==='datetime'?fdt(v):t==='int'?numeric(v):val(v);
const th=(cols)=>cols.map(c=>`<th class="${c.col||''}">${e(c.label||c.key)}</th>`).join('');
function table(rows,cols,{foot=false,cls='',cell=null,rowAction=false}={}){rows=a(rows);return `<div class="ac10-scroll"><table class="ac10-table ${cls}"><thead><tr>${th(cols)}</tr></thead><tbody>${rows.length?rows.map((r,idx)=>`<tr ${rowAction?`data-row="${idx}"`:''}>${cols.map(c=>`<td class="${c.col||''}">${cell?cell(r,c,idx):fmt(r[c.key],c.type)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="ac10-nodata">No data for selected period</td></tr>`}</tbody>${rows.length&&foot?`<tfoot><tr>${cols.map((c,i)=>`<td>${i===0?`Total (${rows.length})`:c.total?(c.type==='money'?money(sum(rows,c.key)):c.type==='int'?numeric(sum(rows,c.key)):''):' '}</td>`).join('')}</tr></tfoot>`:''}</table></div>`}
const niceName=k=>k.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const autoCols=rows=>{const keys=[...new Set(rows.slice(0,20).flatMap(Object.keys))].filter(k=>rows.every(r=>!r[k]||typeof r[k]!=='object'));return keys.map(k=>({key:k,label:niceName(k),type:/^(amount|fare|refund|charge|profit|expense|net_sales|total|commission|paid|receivable|spend|revenue|fuel_cost|payout|expected_payout)$/.test(k)?'money':/pct|percent/.test(k)?'pct':/(^date$|_date$)/.test(k)?'date':undefined,total:/^(amount|fare|refund|charge|profit|expense|net_sales|total|km|fuel_l|seats|bookings|paid|receivable|payout)$/.test(k)}))};
const autoTable=(rows)=>table(a(rows).slice(0,2000),autoCols(a(rows)),{foot:true});
const pres=(name,q)=>`<div class="ac10-presets">${[['7','Last 7 days'],['month','This month'],['last','Last month']].map(([k,label])=>btn(e(label),'preset','subtle',`data-preset="${k}"`)).join('')}</div>`;
function dates(q,{compact=false}={}){return `<form class="ac10-filterform ${compact?'compact':''}" data-filters>${dateInput('from',q.from)}${dateInput('to',q.to)}${pres('',q)}${btn('Apply','filter-apply','primary')}</form>`}
function topNav(tab){return `<nav class="ac10-nav" aria-label="Accounts submenus">${navs.filter(x=>can(x[3])).map(([key,name,ico])=>`<a href="#/accounts/${key}" class="${tab===key?'active':''}">${ic(ico,17)}<span>${name}</span></a>`).join('')}</nav>`}
const tools=(report=false)=>`<div class="ac10-tools">${btn(`${ic('print')} Print`,'print','primary')}${report?btn(`${ic('download')} PDF`,'print','subtle'):''}${btn(`${ic(report?'share':'download')} ${report?'Share':'Download'}`,report?'share':'export','subtle')}</div>`;
function queryUpdated(state,keys){const p=G.query();const next={...p,...keys};location.hash=`#/accounts/${state.tab}${state.id?'/'+state.id:''}?${G.qs(next)}`;}
function summarize(label,v,style){return `<div class="ac10-headstat ${style||''}"><div>${e(label)}</div><b>${v}</b></div>`}
function normalizeForm(form){const o={};new FormData(form).forEach((v,k)=>o[k]=v);return o}
function modal(title,subtitle,body,foot='',kind=''){const m=G.modal({title:`<span class="ac10-modalicon">${ic('receivables',23)}</span><div class="ac10-modalheading"><b>${e(title)}</b><small>${e(subtitle)}</small></div>`,body,foot,size:'lg'});m.el.classList.add('ac10-overlay',...kind.split(/\s+/).filter(Boolean));return m}
async function api(url){return G.get(url)}
function reportsRow(r,key){return `<a class="ac10-report" href="#/accounts/reports/${key}"><span class="ac10-reportico">${ic(r[4],17)}</span><span><b>${e(r[2])}</b><small>${e(r[3])}</small></span>${ic('arrow',14)}</a>`}

async function sales(root,s){
 const q=s.q;const [d,channel]=await Promise.all([api('/accounts/analytics?'+G.qs({from:s.from,to:s.to,basis:s.basis||'travel_date',source:s.source||'all'})),api('/accounts/channels').catch(()=>({otas:[],agents:[]}))]);
 s.rows=a(d.rows);let src=['all',...new Set(a(d.channels).map(x=>x.source))]; const channels=a(d.channels);
 const ts=d.totals||{};
 // Fetch source-scoped aggregates from the authoritative analytics endpoint, not fabricated per-channel values.
 d.byChannelDays=Object.fromEntries(await Promise.all(channels.slice(0,10).map(async ch=>{try{const x=await api('/accounts/analytics?'+G.qs({from:s.from,to:s.to,basis:s.basis||'travel_date',source:ch.source}));return [ch.source,Object.fromEntries(a(x.rows).map(r=>[r.date,r.net_sales]))]}catch(_){return [ch.source,{}]}})));
 // Service and sector pivots can be reconstructed only from booking records.
 const tx=await api('/accounts/transactions?'+G.qs({from:s.from,to:s.to,source:s.source||'all'})).catch(()=>({rows:[]}));d.sourceTransactions=a(tx.rows);
 const routeResult=await api('/routes').catch(()=>({routes:[]}));d.routeList=a(routeResult.routes);
 root.innerHTML=`<div class="ac10-saleshead">${dateInput('from',s.from)}${dateInput('to',s.to)}<div class="ac10-segment" data-seg="basis">${[['travel_date','Travel Date'],['booking_date','Booking Date']].map(([k,v])=>btn(v,'change-basis',s.basis===k?'selected':'',`data-value="${k}"`)).join('')}</div><div class="ac10-segment" data-seg="pivot">${[['date','By Date'],['sector','By Sector'],['service','By Service'],['pnl','P&L']].map(([k,v])=>btn(v,'change-pivot',s.pivot===k?'selected':'',`data-value="${k}"`)).join('')}</div>${sel('sector',[['all','All Sectors']],s.sector)}${sel('service',[['all','All Services'],...a(d.rows).flatMap(r=>r.service?[ [r.service,r.service] ]:[])],s.service)}</div><div class="ac10-saleslower">${sel('source',src.map(x=>[x,x==='all'?'All Channels':x]),s.source)}${btn(`${ic('print')} Print`,'print','primary')}</div><div class="ac10-salesstats">${stat('Sales',money(ts.sales))}${stat('Offers',money(ts.offers),'orange')}${stat('Net Sales',money(ts.net_sales),'blue')}${stat('Bookings',numeric(ts.bookings))}${stat('ASP',money(ts.asp))}${stat('Occupancy',percent(ts.occupancy_pct),'green')}${stat('Fleet Util',percent(ts.fleet_util_pct),'green')}${stat('Cancellation Charges',money(ts.cancel_charges),'orange')}</div>${stat('GST Payable',money(ts.gst),'red ac10-gst')}
 <div class="ac10-section ac10-finance-table" id="ac10-salesgrid"><div class="ac10-table-label">${s.pivot==='date'?'BY CHANNEL':`BY ${s.pivot.toUpperCase()}`}</div>${salesTable(d,s)}</div>`;
 const rerender=()=>root.querySelector('#ac10-salesgrid').innerHTML=`<div class="ac10-table-label">${s.pivot==='date'?'BY CHANNEL':`BY ${s.pivot.toUpperCase()}`}</div>${salesTable(d,s)}`;
 root.addEventListener('click',evt=>{const b=evt.target.closest('[data-ac10="change-basis"],[data-ac10="change-pivot"]');if(!b)return;if(b.dataset.ac10==='change-basis'){s.basis=b.dataset.value;queryUpdated(s,{basis:s.basis,pivot:s.pivot});}else{s.pivot=b.dataset.value;root.querySelectorAll('[data-seg="pivot"] button').forEach(x=>x.classList.toggle('selected',x===b));rerender();}});
}
function salesTable(d,s){const rows=a(d.rows).slice().reverse(),t=d.totals||{};const cols=[{key:'date',label:s.basis==='booking_date'?'BOOKING DATE':'TRAVEL DATE',type:'date'},...['bookings','seats','occupancy_pct','fleet_util_pct','asp','sales','offers','net_sales','gst'].map(x=>({key:x,label:({occupancy_pct:'OCCUPANCY',fleet_util_pct:'FLEET UTIL',net_sales:'NET SALES'}[x]||x.toUpperCase()),type:/pct/.test(x)?'pct':/^(asp|sales|offers|net_sales|gst)$/.test(x)?'money':'int',total:/^(bookings|seats|sales|offers|net_sales|gst)$/.test(x),col:x==='net_sales'?'ac10-strongblue':x==='offers'?'ac10-orange':x==='gst'?'ac10-red':''})),...a(d.channels).map(x=>({key:`src_${x.source}`,label:x.source.toUpperCase(),type:'money',col:'ac10-purple'}))];
 if(s.pivot==='date')return table(rows.map(r=>({...r,...Object.fromEntries(a(d.channels).map(x=>[`src_${x.source}`,d.byChannelDays?.[x.source]?.[r.date]??null]))})),cols,{foot:true});
 if(s.pivot==='pnl')return table(rows,[{key:'date',label:'TRAVEL DATE',type:'date'},...['bookings','seats','net_sales','cancel_charges','expense','profit'].map(x=>({key:x,label:niceName(x),type:/bookings|seats/.test(x)?'int':'money',total:true}))],{foot:true});
 if(s.pivot==='service'||s.pivot==='sector'){
 const sectors=Object.fromEntries(a(d.routeList).map(r=>[r.service_number||r.service,r]));const groups=grouped(a(d.sourceTransactions).filter(x=>x.type==='booking'&&/confirm|complete|paid/i.test(x.status||'')),r=>s.pivot==='service'?(r.service||'Unassigned'):(sectors[r.service]?.origin_city||sectors[r.service]?.origin||'Unknown')+' → '+(sectors[r.service]?.destination_city||sectors[r.service]?.destination||'Unknown'));
 const summaries=Object.entries(groups).map(([name,x])=>({name,bookings:x.length,seats:x.reduce((v,r)=>v+String(r.seats||'').split(',').filter(Boolean).length,0),net_sales:sum(x,'net'),avg_fare:x.length?sum(x,'net')/x.length:0}));
 return summaries.length?table(summaries,[{key:'name',label:s.pivot==='service'?'SERVICE':'SECTOR'}, {key:'bookings',label:'BOOKINGS',type:'int',total:true},{key:'seats',label:'SEATS',type:'int',total:true},{key:'net_sales',label:'NET SALES',type:'money',total:true},{key:'avg_fare',label:'AVG BOOKING',type:'money'}],{foot:true}):empty('Service/sector breakdown is unavailable for these dates');}
 return empty('No sales breakdown available');
}
async function transactions(root,s){const d=await api('/accounts/transactions?'+G.qs({from:s.from,to:s.to,q:s.search||'',source:s.source||'all'}));s.rows=a(d.rows);s.source=s.source||'all';let rows=s.rows;
 const draw=()=>{let filtered=rows.filter(r=>s.kind==='all'||(s.kind==='credits'&&r.type==='booking')||(s.kind==='debits'&&r.type==='cancellation'));root.querySelector('[data-ac10-tbody]').innerHTML=transactionBody(filtered);root.querySelector('[data-ac10-count]').textContent=filtered.length+' rows';};
 root.innerHTML=`<div class="ac10-saleshead">${dateInput('from',s.from)}${dateInput('to',s.to)}<div class="ac10-segment">${btn('Travel Date','nop','selected')}${btn('Booked On','nop','')}</div>${sel('source',[['all','All Agents'],['redbus','RedBus'],['abhibus','AbhiBus'],['paytm','Paytm'],['website','Website'],['agent','Agent'],['branch','Branch']],s.source)}${sel('service',[['all','All Services']],s.service)}<div class="ac10-segment">${[['all','All'],['credits','Credits'],['debits','Debits']].map(([k,v])=>btn(v,'transaction-kind',s.kind===k?'selected':'',`data-value="${k}"`)).join('')}</div></div><div class="ac10-saleslower"><label class="ac10-search">${ic('search')}<input data-live-search placeholder="PNR, phone, passenger or agent" value="${e(s.search||'')}"></label>${btn(`${ic('download')} Download`,'export','success')}</div><div class="ac10-txstats">${stat('Credits',money(sum(rows.filter(r=>r.type==='booking'),'total')),'green')}${stat('Debits',money(sum(rows.filter(r=>r.type==='cancellation'),'refund')),'red')}${stat('Net',money(sum(rows,'total')),'blue')}</div><div class="ac10-transactionmini">${['website','branch','ota'].map(x=>stat(x==='website'?'SAVE TRIP / OPERATOR':x==='branch'?'BRANCHES OWN':'OTAs → PAY',money(rows.filter(r=>x==='ota'?['redbus','abhibus','paytm'].includes(r.source):r.source===x).reduce((sum,r)=>sum+n(r.total),0)))).join('')}</div><div class="ac10-section"><div class="ac10-listcount" data-ac10-count></div><div class="ac10-scroll"><table class="ac10-table ac10-payments"><thead><tr>${['Agent','PNR','Service','Seats','Type','DOJ','Booked At','Amount','Paid by · Money with','Status'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody data-ac10-tbody></tbody></table></div></div>`;draw();root.querySelector('[data-live-search]').oninput=ev=>{s.search=ev.target.value.toLowerCase();rows=s.rows.filter(r=>`${r.pnr} ${r.phone} ${r.passenger} ${r.source}`.toLowerCase().includes(s.search));draw()};root.querySelectorAll('[data-ac10="transaction-kind"]').forEach(b=>b.onclick=()=>{s.kind=b.dataset.value;root.querySelectorAll('[data-ac10="transaction-kind"]').forEach(z=>z.classList.toggle('selected',z===b));draw();});root.addEventListener('click',evt=>{const tr=evt.target.closest('[data-pnr]');if(tr){G.bookingModal(tr.dataset.pnr);}})
}
function transactionBody(rows){return rows.length?rows.map(r=>`<tr data-pnr="${e(r.pnr)}" class="ac10-rowclick"><td>${e(r.source||'—')}</td><td><b class="ac10-mono">${e(r.ticket||r.pnr)}</b><small>${e(r.pnr)}</small></td><td><b class="ac10-link">${e(r.service)}</b></td><td>${e(r.seats)}</td><td><span class="ac10-type ${r.type==='booking'?'ok':'warn'}">${r.type==='booking'?'BOOKING':'PAX CANCEL'}</span></td><td>${fdate(r.travel_date)}</td><td>${fdt(r.date)}</td><td class="ac10-txamount ${n(r.total)<0?'red':''}">${money(Math.abs(n(r.total)))}</td><td><b>${e(r.method||r.payment||'—')}</b><small>${e(r.source)} · ${e(r.booked_by||'Operator')}</small></td><td><span class="ac10-status ${/confirm|complete|paid/i.test(r.status)?'ok':'bad'}">${e(r.status||'—')}</span></td></tr>`).join(''):`<tr><td colspan="10" class="ac10-nodata">No transactions found</td></tr>`}
function receivableRows(rows){const cols=[{key:'display_name',label:'CHANNEL'}, {key:'channel_type',label:'RATE'}, {key:'bookings',label:'PNR',type:'int',total:true},{key:'total',label:'FARE',type:'money',total:true},{key:'commission',label:'OFFERS / COMMISSION',type:'money',total:true},{key:'gst_on_commission',label:'TAX',type:'money',total:true},{key:'tds',label:'TDS',type:'money',total:true},{key:'deductions',label:'TOTAL DEDUCTIONS',type:'money',total:true},{key:'paid',label:'PAID',type:'money',total:true},{key:'receivable',label:'RECEIVABLES',type:'money',total:true},{key:'actions',label:'ACTIONS'}];return table(rows,cols,{foot:true,cls:'ac10-rec-table',cell:(r,c)=>c.key==='actions'?`<div class="ac10-ledger-actions">${btn('Credit','ledger-open','green',`data-channel="${e(r.channel_key)}" data-ledtype="credit"`)}${btn('Debit','ledger-open','amber',`data-channel="${e(r.channel_key)}" data-ledtype="debit"`)}${btn(`${ic('reports',13)} Ledger`,'ledger-open','light',`data-channel="${e(r.channel_key)}" data-ledtype="credit"`)}</div>`:c.key==='receivable'?`<strong class="ac10-green">${money(r.receivable)}</strong>`:fmt(r[c.key],c.type)})}
async function receivables(root,s){const d=await api('/accounts/receivables?'+G.qs({from:s.from,to:s.to}));s.rows=a(d.rows);s.type=s.type||'all';const sums=()=>{const rows=s.rows;return `<div class="ac10-recstats">${stat('Collected',money(sum(rows,'total')))}${stat('Total Deductions',money(sum(rows,'deductions')),'orange')}${stat('Paid',money(sum(rows,'paid')),'blue')}${stat('Receivables',money(sum(rows,'receivable')),'green')}</div>`};root.innerHTML=`<div class="ac10-row-between">${dates(s,{compact:true})}<div class="ac10-tools">${btn(`${ic('print')} Print`,'print','primary')}${btn(`${ic('download')} Download`,'export','success')}</div></div><div class="ac10-segment">${[['all','All'],['operator','SaveTrip'],['ota','OTAs'],['agent','Agents'],['branch','Staff']].map(([k,v])=>btn(v,'receivables-kind',s.type===k?'selected':'',`data-value="${k}"`)).join('')}</div>${sums()}<div data-ac10-restable>${receivableRows(s.rows)}</div>`;root.querySelectorAll('[data-ac10="receivables-kind"]').forEach(b=>b.onclick=()=>{s.type=b.dataset.value;root.querySelectorAll('[data-ac10="receivables-kind"]').forEach(x=>x.classList.toggle('selected',x===b));const xs=s.rows.filter(r=>s.type==='all'||r.channel_type===s.type);root.querySelector('[data-ac10-restable]').innerHTML=receivableRows(xs);});}
async function ledgerDialog(channel,type='credit'){
 if(!can('accounts.ledger'))return G.toast('Ledger permission required','bad');
 const d=await api('/accounts/ledger?channel_key='+encodeURIComponent(channel));let t=type;
 const body=`<div class="ac10-ledstat">${summarize('ACCRUED',money(d.total_debits))}${summarize('RECEIVED',money(d.total_credits))}${summarize('BALANCE',money(d.balance),'ac10-strongblue')}</div><div class="ac10-segment fill">${btn('Payment received','ledger-type',t==='credit'?'selected':'',`data-value="credit"`)}${btn('Debit (owed)','ledger-type',t==='debit'?'selected':'',`data-value="debit"`)}</div><form data-ledger-form><div class="ac10-grid-2">${field('₹ Amount','amount','','number','required min="0.01" step="0.01"')}${field('Date','date',today(),'date','required')}</div>${field('Note (e.g. UTR / reference) — optional','note','','text','maxlength="250"')}<button class="ac10-btn primary full" type="submit">${t==='credit'?'Record payment':'Record debit'}</button></form><h3>HISTORY</h3><div class="ac10-led-history">${a(d.entries).slice().reverse().map(x=>`<div class="ac10-led-line"><div><b>${e(x.kind==='manual'?'Manual entry':x.kind==='ticket'?'Booking '+x.ref:'Cancellation '+x.ref)}</b><small>${fdate(x.date)} · ${e(x.note)}</small></div><strong class="${n(x.debit)>0?'ac10-red':'ac10-green'}">${n(x.debit)>0?'+ '+money(x.debit):'- '+money(x.credit)}</strong></div>`).join('')||empty('No manual entries yet')}</div>`;
 const m=modal(channel.replace(/^\w+:/,''),'Settlement ledger · '+channel,body,'','ac10-small-modal');
 m.$$('button[data-ac10="ledger-type"]').forEach(b=>b.onclick=()=>{t=b.dataset.value;m.$$('button[data-ac10="ledger-type"]').forEach(x=>x.classList.toggle('selected',x===b));m.$('button[type="submit"]').textContent=t==='credit'?'Record payment':'Record debit'});
 m.$('[data-ledger-form]').onsubmit=async evt=>{evt.preventDefault();const v=normalizeForm(evt.currentTarget);if(!(Number(v.amount)>0))return G.toast('Enter a valid amount','bad');if(!(await G.confirm(`Record ${t==='credit'?'payment received':'debit owed'} of ${money(v.amount)}?`,{ok:'Record'})))return;try{await G.post('/accounts/ledger',{channel_key:channel,type:t,amount:Number(v.amount),date:v.date,note:v.note});m.close();G.toast('Ledger entry recorded','ok');if(location.hash.startsWith('#/accounts'))window.dispatchEvent(new Event('hashchange'));}catch(err){G.err(err);}};
}
async function reports(root,s){if(!s.id)return reportCatalogue(root,s);return reportDetail(root,s)}
function reportCatalogue(root){root.innerHTML=`<div class="ac10-reports-home"><div class="ac10-row-between"><div><h2>Reports</h2><p>Pick a report, choose the period, then view, print or save it as PDF.</p></div><label class="ac10-search sm">${ic('search')}<input data-report-find placeholder="Search 13 reports" autocomplete="off"></label></div><div class="ac10-report-grid">${['FLEET','CREW','BOOKINGS','CUSTOMERS','FINANCE'].map(k=>`<section><h3>${k}</h3>${cat.filter(r=>r[0]===k).map(r=>reportsRow(r,r[1])).join('')}</section>`).join('')}</div></div>`;root.querySelector('[data-report-find]').oninput=ev=>{const q=ev.target.value.toLowerCase();root.querySelectorAll('.ac10-report').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q))}}
function reportColSet(id,key,rows){const cols={
 'fleet-operations':{by_bus:[['vehicle','Bus'],['days_ran','Trips'],['km','Km (GPS)'],['fuel_l','Fuel (L)'],['kmpl','km/L']],rows:[['date','Date'],['departure_time','Dep'],['service','Service'],['route','Route'],['vehicle','Bus'],['km','Km'],['fuel_l','Fuel (L)'],['kmpl','km/L'],['seats','Seats'],['occupancy_pct','Occupancy']]},
 'point-usage':{boarding:[['point','Boarding point'],['bookings','Bookings'],['seats','Seats'],['share_pct','Share'],['days_used','Days used'],['amount','Amount']],dropping:[['point','Dropping point'],['bookings','Bookings'],['seats','Seats'],['share_pct','Share'],['days_used','Days used'],['amount','Amount']],pairs:[['point','Boarding → Dropping'],['bookings','Bookings'],['seats','Seats'],['amount','Amount']]},
 'metro-bookings':{points:[['point','Boarding point'],['pnrs','PNRs'],['pax','Seats'],['fare','Metro fare']],rows:[['travel_date','Date'],['service_number','Service'],['pnr','PNR'],['source','Source'],['leg','Metro'],['boarding_point','Boarding'],['seats','Seats'],['metro_fare','Metro fare'],['amount','Revenue']]},
 'van-bookings':{rows:[['travel_date','Date'],['pnr','PNR'],['boarding_point','Boarding'],['seats','Seats'],['amount','Revenue']]},
 'point-performance':{ranking:[['rank','#'],['point','Pickup point'],['bookings','PNRs'],['seats','Seats'],['share_pct','Share'],['days_used','Trips booked'],['seats_per_trip','Seats/trip'],['amount','Revenue']]},
 'station-performance':{pairs:[['pair','From → To'],['bookings','PNRs'],['seats','Seats'],['amount','Revenue']],services:[['service','Service'],['route','Route'],['time','Dep'],['trips','Trips'],['bookings','PNRs'],['seats','Seats'],['seats_per_trip','Seats/trip'],['avg_fare','Avg fare'],['amount','Revenue'],['pairs','Pairs'],['top_pair','Top pair'],['through_pct','End to end']]},
 'no-shows':{rows:[['travel_date','Date'],['service_number','Service'],['vehicle_number','Bus'],['pnr','PNR'],['passenger_name','Passenger'],['contact_phone','Phone'],['boarding_point','Boarding'],['source','Source'],['seat','Seat'],['fare','Fare']]},
 'cancellations':{rows:[['travel_date','Date'],['service_number','Service'],['pnr','PNR'],['passenger_name','Passenger'],['contact_phone','Phone'],['boarding_point','Boarding'],['source','Source'],['by','By'],['seats','Seats'],['refund','Refund'],['charge','Charge']]},
 'trip-pnl':{rows:[['date','Date'],['departure_time','Dep'],['service','Service'],['route','Route'],['vehicle','Bus'],['seats','Seats'],['occupancy_pct','Occupancy'],['net_sales','Net Sales'],['expense','Expense'],['profit','Profit']]},
 'expenses':{categories:[['category','Category'],['type','Type'],['amount','Amount'],['share_pct','Share'],['trips','Trips'],['avg_per_trip','Avg/trip']]},
 'driver-behavior':{drivers:[['driver','Driver'],['trips','Trips'],['score','Score'],['hard_brake','Hard brake'],['over_speed','Overspeed'],['idling','Idling'],['top_speed','Top speed']],rows:[['date','Date'],['service','Service'],['vehicle','Bus'],['driving_score','Score'],['hard_brake','Hard brake'],['over_speed','Overspeed'],['idling','Idling']]},
 'staff-duty':{rows:[['date','Date'],['service','Service'],['vehicle','Bus'],['status','Status'],['km','Km'],['amount','Amount']]},
 'frequent-travellers':{rows:[['name','Passenger'],['phone','Phone'],['trips','Trips'],['seats','Seats'],['spend','Spend'],['avg_trip','Avg/trip'],['cancelled','Cancelled'],['first_trip','First trip'],['last_trip','Last trip'],['channels','Channels']]}
 };return (cols[id]?.[key]||[]).map(([k,l])=>({key:k,label:l,type:/amount|fare|sales|expense|profit|revenue|refund|charge|spend/.test(k)?'money':/(pct|share|occupancy|through)/.test(k)?'pct':/(^date$|_date$|_trip$)/.test(k)?'date':undefined,total:/^(amount|seats|bookings|pnrs|expense|profit|refund|fare|km|fuel_l)$/.test(k)}))}
function reportTable(id,key,rows){const cols=reportColSet(id,key,rows);return cols.length?table(rows,cols,{foot:true,cls:'ac10-report-data'}):autoTable(rows)}
function reportSummary(d,id){const s=d.summary||{};let entries=Object.entries(s).filter(([,v])=>typeof v==='number').map(([k,v])=>[niceName(k),v,/pct|percent/.test(k)?'pct':/fare|revenue|amount|expense|profit|refund|charge|spend|paid/.test(k)?'money':'int']);if(!entries.length){entries=Object.entries(d).filter(([k,v])=>Array.isArray(v)).map(([k,v])=>[niceName(k),v.length,'int'])}return `<div class="ac10-reportstats">${entries.slice(0,12).map(([k,v,t])=>stat(k,fmt(v,t))).join('')}</div>`}
async function reportDetail(root,s){const q=G.query();const key=s.id;const c=cat.find(r=>r[1]===key);if(!c){root.innerHTML=empty('Report not found');return}
 let extra={};if(key==='staff-duty'&&q.staff_id)extra.staff_id=q.staff_id;
 let d=await api('/accounts/reports/'+encodeURIComponent(key)+'?'+G.qs({from:s.from,to:s.to,...extra}));s.data=d;s.rows=Object.values(d).filter(Array.isArray).flat().filter(v=>v&&typeof v==='object');
 const filters=`<div class="ac10-reportfilter">${key==='staff-duty'?`<label class="ac10-select"><select name="staff_id"><option value="">Select driver / staff</option>${s.staffList?.map(x=>`<option value="${e(x.id)}" ${x.id==q.staff_id?'selected':''}>${e(x.name)}</option>`).join('')||''}</select>${ic('chevron')}</label>`:''}${key==='fleet-operations'||key==='driver-behavior'||key==='trip-pnl'?sel('bus',[['all','All buses']],q.bus):''}${key==='metro-bookings'||key==='van-bookings'?`<div class="ac10-segment">${[['both','Pickup + Drop'],['pickup','Metro pickup'],['drop','Metro drop']].map(([k,l])=>btn(l,'report-toggle',(s.reportMode||'both')===k?'selected':'',`data-value="${k}"`)).join('')}</div>`:''}${dateInput('from',s.from)}${dateInput('to',s.to)}${pres()}${btn('Apply','report-apply','primary')}</div>`;
 let sections=Object.entries(d).filter(([k,v])=>Array.isArray(v));
 if(['metro-bookings','van-bookings'].includes(key)&&s.reportMode==='drop')sections=sections.map(([k])=>[k,[]]);
 root.innerHTML=`<div class="ac10-row-between ac10-reporttitle"><div><a href="#/accounts/reports" class="ac10-back">${ic('back',13)} Reports</a><h2>${e(c[2])}</h2></div>${tools(true)}</div>${filters}<p class="ac10-subtext">${e(c[3])}${key==='metro-bookings'?' · Metro fares are estimates unless verified against the feeder provider.':''}${key==='fleet-operations'?' · Kilometres and fuel are values supplied by the GDS, not independently verified GPS evidence.':''}</p>${key==='staff-duty'&&!q.staff_id?empty('Select a driver or staff member to see their statement.'):reportSummary(d,key)}${s.reportMode==='drop'&&['metro-bookings','van-bookings'].includes(key)?'<p class="ac10-note">Drop-leg data is not exposed by the current GDS report API.</p>':''}${key==='staff-duty'&&!q.staff_id?'':sections.map(([k,v])=>`<section class="ac10-report-section"><h3>${niceName(k)} <span>· ${v.length}</span></h3>${reportTable(key,k,v)}</section>`).join('')||empty()}`;
 root.querySelectorAll('[data-ac10="report-toggle"]').forEach(b=>b.onclick=()=>{s.reportMode=b.dataset.value;root.querySelectorAll('[data-ac10="report-toggle"]').forEach(x=>x.classList.toggle('selected',x===b));const tables=root.querySelectorAll('.ac10-report-section');tables.forEach(t=>{t.hidden=s.reportMode==='drop'});if(s.reportMode==='drop')G.toast('Drop-leg detail is unavailable from the current report API','bad')});
 if(key==='staff-duty'){const c=root.querySelector('[name=staff_id]');if(c)c.onchange=()=>queryUpdated(s,{staff_id:c.value});}
}
async function invoices(root,s){const d=await api('/accounts/documents');s.invoiceData=d;const docs=a(d.documents),bal=d.balance||{};
 const groups=grouped(docs,r=>(r.month||r.date?.slice(0,7)||'Other'));root.innerHTML=`<div class="ac10-invoice-panel"><div class="ac10-row-between"><div><small>OUTSTANDING BALANCE</small><h2>${money(bal.balance)}</h2><p>As per Operator Statement ${e(bal.statement||'—')} ${docs.length?`<a href="#/accounts/invoices" data-ac10="statement">View</a>`:''}</p></div><div>${btn(`${ic('clock')} Refresh`,'refresh','subtle')}${can('accounts.ledger')?btn('₹ Pay','invoice-pay','primary'):''}</div></div></div><div class="ac10-inv-filters">${sel('invtype',[['all','All types'],...new Set(docs.map(x=>x.label).filter(Boolean)).values()].map(x=>Array.isArray(x)?x:[x,x]),'all')}${sel('invyear',[['all','All years'],...new Set(docs.map(x=>String(x.date||'').slice(0,4)).filter(Boolean))].map(x=>Array.isArray(x)?x:[x,x]),'all')}${btn('Current statement','invoice-statement','subtle')}</div>${Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0])).map(([month,items])=>`<section class="ac10-invoicemonth"><div class="ac10-row-between"><h3>${e(month)}</h3>${btn(`${ic('download')} Download all`,'invoice-download','link',`data-month="${e(month)}"`)}</div>${items.map((r,i)=>`<div class="ac10-invoicerow"><span>${e(r.label||r.kind)}</span><span>${e(r.name)}</span><div>${btn(`${ic('eye',12)} View`,'invoice-view','light',`data-doc="${e(r.id)}"`)}${btn(`${ic('download',12)} PDF`,'invoice-pdf','link',`data-doc="${e(r.id)}"`)}</div></div>`).join('')}</section>`).join('')||empty('No invoices or statements')}`;
}
function invoiceView(r){return modal(r.label||'Statement',r.name||'',`<div class="ac10-reportstats">${stat('Period',e(r.month||r.date||'—'))}${stat('Amount',fmoney(r.amount))}${stat('Status',e(r.status||'—'))}</div><p class="ac10-note">This is a document summary from your GDS. A provider-issued PDF has not been supplied by the current API; do not treat this printout as the original tax invoice.</p>${btn(`${ic('print')} Print summary`,'print','primary')}`,'','ac10-small-modal')}
async function invoicePay(d){const bal=d.balance||{};const m=modal('Record payment','Operator statement payment',`<form data-invoice-form>${field('Amount (₹)','amount',bal.balance||'','number','required min="0.01" step="0.01"')}${field('UTR / Reference','reference','','text','required')}<p class="ac10-note">This records a manual payment reference. It does not charge a bank account or verify receipt.</p><button type="submit" class="ac10-btn primary full">Record payment</button></form>`,'','ac10-small-modal');m.$('[data-invoice-form]').onsubmit=async evt=>{evt.preventDefault();const v=normalizeForm(evt.currentTarget);if(!(n(v.amount)>0))return;if(!await G.confirm(`Record manual payment of ${money(v.amount)}?`,{ok:'Record'}))return;try{await G.post('/accounts/documents/pay',{amount:Number(v.amount),reference:v.reference});m.close();G.toast('Manual payment recorded','ok');window.dispatchEvent(new Event('hashchange'))}catch(err){G.err(err)}}}
async function reconciliation(root,s){if(s.id)return reconciliationDetail(root,s);const [res,cfg]=await Promise.all([api('/reconciliation/settlements'),api('/reconciliation/config')]);s.imports=a(res.imports);s.configs=a(cfg);
 root.innerHTML=`<div class="ac10-row-between ac10-reporttitle"><div><h2>Settlement ledger</h2><p>Uploaded Invoices</p></div><div class="ac10-tools"><span class="ac10-status ok">● LIVE</span>${btn(`${ic('plus')} Upload Invoice`,'reconcile-toggle','primary')}</div></div><div class="ac10-dropzone" data-ac10-uploadarea hidden><span>${ic('download',26)}</span><b>DROP TO UPLOAD</b><strong>Drop your OTA invoice here</strong><small>or click anywhere to browse</small><div class="ac10-formatbadges"><span>PDF</span><span>XLSX</span><span class="active">CSV</span></div><div>${sel('ota',[['','Select OTA'],...s.configs.map(x=>[x.ota_slug,x.ota_display_name||x.ota_slug])],'')}&nbsp; <label class="ac10-file"><input type="file" accept=".csv,text/csv" data-ota-file>CSV</label></div><p>The currently connected reconciliation API accepts CSV with PNR, fare, commission, payout and optional type. PDF/XLSX need a document parser integration.</p>${btn('Upload & Match','reconcile-upload','primary')}</div><div class="ac10-section"><div class="ac10-row-between"><h3>SETTLEMENT LEDGER <small>UPLOADED INVOICES</small></h3><span class="ac10-status ok">LIVE</span></div>${table(s.imports,[{key:'ota_slug',label:'OTA'}, {key:'billing_period_start',label:'PERIOD',type:'date'}, {key:'invoice_number',label:'INVOICE'}, {key:'total_lines_parsed',label:'PNRS',type:'int'}, {key:'status',label:'STATUS'}, {key:'matched_count',label:'MATCHED',type:'int'}, {key:'mismatched_count',label:'ISSUES',type:'int'}, {key:'created_at',label:'UPLOADED',type:'datetime'}, {key:'view',label:''}],{cell:(r,c)=>c.key==='view'?`<a href="#/accounts/reconciliation/${e(r.id)}" class="ac10-btn primary tiny">${ic('eye',14)}</a>`:c.key==='status'?`<span class="ac10-status ok">${e(r.status)}</span>`:fmt(r[c.key],c.type)})}</div>`;
 root.querySelector('[data-ota-file]')?.addEventListener('change',ev=>{root.querySelector('.ac10-file').lastChild.textContent=ev.target.files?.[0]?.name||'CSV'});
}
async function reconciliationDetail(root,s){const d=await api('/reconciliation/settlements/'+encodeURIComponent(s.id));s.reconciliation=d;s.rows=a(d.lines);const diffs=s.rows.filter(x=>x.status!=='matched');s.diffFilter=s.diffFilter||'all';root.innerHTML=`<div class="ac10-row-between ac10-reporttitle"><div><a href="#/accounts/reconciliation" class="ac10-back">${ic('back',14)} Uploaded invoices</a><h2>Reconciliation — ${e(d.ota_slug)}</h2><p>${e(d.file_name)}</p></div>${tools(true)}</div><div class="ac10-reconhero">${stat('OTA paid',money(d.ota_payout))}${stat('GDS expected',money(d.our_expected))}${stat('Difference',money(d.difference),n(d.difference)<0?'red':'green')}${stat('PNRs',numeric(d.total_lines_parsed))}</div><h3>Reconciliation summary</h3><div class="ac10-reconsummary">${stat('Matched',numeric(d.matched_count),'green')}${stat('Mismatched',numeric(d.mismatched_count),'red')}${stat('Not in GDS',numeric(d.unmatched_ota_count),'orange')}</div><div class="ac10-segment ac10-reconfilters">${[['all','All differences'],['matched','Matched'],['mismatched','Fare / payout differs'],['unmatched_ota','Missing in GDS']].map(([k,l])=>btn(l+(k==='all'?` ${diffs.length}`:''),'recon-kind',s.diffFilter===k?'selected':'',`data-value="${k}"`)).join('')}</div><div data-recon-table>${renderReconRows(s)}</div>${diffs.length?`<div class="ac10-note">${diffs.length} reconciliation differences need review. Automated payment settlement is not performed here.</div>`:''}`;root.querySelectorAll('[data-ac10="recon-kind"]').forEach(b=>b.onclick=()=>{s.diffFilter=b.dataset.value;root.querySelectorAll('[data-ac10="recon-kind"]').forEach(x=>x.classList.toggle('selected',x===b));root.querySelector('[data-recon-table]').innerHTML=renderReconRows(s);});}
function renderReconRows(s){const rows=s.rows.filter(r=>s.diffFilter==='all'||r.status===s.diffFilter);return table(rows,[{key:'pnr',label:'PNR'},{key:'booking_status',label:'OURS'},{key:'type',label:'RED BUS'},{key:'payout',label:'OTA PAYS',type:'money'},{key:'expected_payout',label:'WE EXPECT',type:'money'},{key:'difference',label:'DIFFERENCE',type:'money'},{key:'reason',label:'WHAT DIFFERS'},{key:'status',label:'STATUS'}],{foot:true})}
async function agentSettings(root,s){let [channels,cfg]=await Promise.all([api('/accounts/channels'),api('/reconciliation/config').catch(()=>[])]);s.channels=channels;s.configs=a(cfg);s.agentTab=s.agentTab||'otas';const otas=s.configs;const agents=a(channels.agents);
 root.innerHTML=`<div class="ac10-row-between ac10-agenthead"><div class="ac10-pills">${btn('OTA Configurations '+otas.length,'agent-tab',s.agentTab==='otas'?'selected':'',`data-value="otas"`)}${btn('Agent Configurations '+agents.length,'agent-tab',s.agentTab==='agents'?'selected':'',`data-value="agents"`)}</div>${btn(`${ic('plus',14)} ${s.agentTab==='otas'?'Add OTA':'Add Agent'}`,'agent-add','primary')}</div><div data-agent-list>${renderAgents(s)}</div>`;root.querySelectorAll('[data-ac10="agent-tab"]').forEach(b=>b.onclick=()=>{s.agentTab=b.dataset.value;root.querySelectorAll('[data-ac10="agent-tab"]').forEach(x=>x.classList.toggle('selected',x===b));root.querySelector('[data-ac10="agent-add"]').innerHTML=`${ic('plus',14)} ${s.agentTab==='otas'?'Add OTA':'Add Agent'}`;root.querySelector('[data-agent-list]').innerHTML=renderAgents(s)});
}
function renderAgents(s){if(s.agentTab==='otas')return s.configs.length?s.configs.map((r,i)=>`<div class="ac10-agentcard"><div class="ac10-row-between"><strong>${e(r.ota_display_name||r.ota_slug)}</strong><div class="ac10-tools"><span class="ac10-status ${r.is_active?'ok':'bad'}">${r.is_active?'Active':'Inactive'}</span><button type="button" class="ac10-switch ${r.is_active?'on':''}" data-ac10="agent-toggle" data-index="${i}" aria-label="Toggle OTA configuration"></button>${btn(ic('edit'),'agent-edit','outlined',`data-index="${i}" title="Edit"`)}${btn(ic('trash'),'agent-delete','outlined danger',`data-index="${i}" title="Remove"`)}</div></div><small>Code: ${e(r.ota_slug)}</small><div class="ac10-agentproperties">${[['Commission',`${n(r.commission_percent).toFixed(2)}%`],['Commission Base',r.commission_base||'Fare only'],['Tax on Fare',`${n(r.gst_on_commission_percent)}%`],['Tax Receivable',r.tax_receivable_from_ota?'Yes':'—'],['TDS',`${n(r.tds_percent)}%`],['GST on Comm.',`${n(r.gst_on_commission_percent)}%`],['Mode',r.settlement_mode||'DOJ'],['Commission kept on passenger cancel',r.commission_kept_on_passenger_cancel?'Yes':'No'],['Tolerance',money(r.match_tolerance??0)]].map(([k,v])=>`<div><small>${e(k)}</small><b>${e(v)}</b></div>`).join('')}</div><small>Verifications / matched / issues are available after importing a settlement file.</small></div>`).join(''):empty('No OTA configurations');return a(s.channels.agents).length?a(s.channels.agents).map((r,i)=>`<div class="ac10-agentcard"><div class="ac10-row-between"><strong>${e(s.localAgentTerms?.[i]?.name??r.name)}</strong><div class="ac10-tools"><span class="ac10-status ok">Agent</span>${btn(ic('eye'),'agent-view','outlined',`data-index="${i}" title="View ledger"`)}${btn(ic('edit'),'agent-edit','outlined',`data-index="${i}" title="Edit financial terms"`)}</div></div><small>Code: ${e(s.localAgentTerms?.[i]?.phone??r.phone)} ${r.__preview?'<span class="ac10-status warn">Preview only</span>':''}</small><p class="ac10-note">Uses GDS default commission unless an authorized agent-specific configuration is available.</p><div class="ac10-agentproperties"><div><small>Commission</small><b>${n(s.localAgentTerms?.[i]?.commission_pct??r.commission_pct)}%</b></div><div><small>Wallet</small><b>Use ledger to inspect</b></div><div>${btn(`${ic('plus',13)} Record payment`,'ledger-open','green',`data-channel="${e(r.channel_key)}" data-ledtype="credit"`)}</div><div>${btn('Debit / adjustment','ledger-open','amber',`data-channel="${e(r.channel_key)}" data-ledtype="debit"`)}</div><div>${btn('Ledger','ledger-open','outlined',`data-channel="${e(r.channel_key)}" data-ledtype="credit"`)}</div></div></div>`).join(''):empty('No agents configured')}
function agentTermsDialog(s,idx,root){
 const isNew=idx===null;const r=isNew?{name:'',phone:'',commission_pct:0}:a(s.channels.agents)[idx];if(!r)return;
 const existing=!isNew?(s.localAgentTerms?.[idx]||{}):{};
 const modalTitle=isNew?'Add Agent Configuration':'Edit Agent Configuration';
 const body=`<div class="ac10-backend-note">${ic('filter')} <b>UI preview</b> — agent-specific financial settings have no write endpoint yet. Saving updates this browser view only; refresh discards the changes.</div><form data-agent-terms-form>
 <div class="ac10-grid-4">
 ${field('Agent name','name',existing.name??r.name,'text','required')}
 ${field('Phone / agent code','phone',existing.phone??r.phone,'text','required')}
 ${field('Commission %','commission_pct',existing.commission_pct??r.commission_pct??0,'number','required min="0" max="100" step="0.01"')}
 ${field('Balance held for agent (₹)','balance',existing.balance??r.balance??0,'number','min="0" step="0.01"')}
 ${field('Credit limit (₹)','credit_limit',existing.credit_limit??r.credit_limit??0,'number','min="0" step="0.01"')}
 ${field('Payment cycle (days)','settlement_cycle_days',existing.settlement_cycle_days??r.settlement_cycle_days??7,'number','min="0"')}
 <label class="ac10-field"><span>Commission base</span>${sel('commission_base',[['fare_only','Fare Only'],['fare_plus_gst','Fare + GST']],existing.commission_base??'fare_only')}</label>
 <label class="ac10-field"><span>Settlement mode</span>${sel('settlement_mode',[['DOJ','DOJ (Date of Journey)'],['DOB','DOB (Date of Booking)'],['weekly','Weekly']],existing.settlement_mode??'DOJ')}</label>
 ${field('Tax on fare %','tax_on_fare_percent',existing.tax_on_fare_percent??0,'number','step="0.01" min="0"')}
 ${field('TDS %','tds_percent',existing.tds_percent??0,'number','step="0.01" min="0"')}
 ${field('GST on commission %','gst_on_commission_percent',existing.gst_on_commission_percent??18,'number','step="0.01" min="0"')}
 ${field('Match tolerance (₹)','match_tolerance',existing.match_tolerance??1,'number','step="0.01" min="0"')}
 </div>
 <div class="ac10-grid-2"><label class="ac10-checkbox"><input type="checkbox" name="is_active" ${(existing.is_active??r.is_active??true)?'checked':''}> Active</label><label class="ac10-checkbox"><input type="checkbox" name="independent_commission" ${(existing.independent_commission??true)?'checked':''}> Use custom agent terms (not defaults)</label></div>
 <div class="ac10-modalbuttons"><button type="button" class="ac10-btn subtle" data-close>Cancel</button><button type="submit" class="ac10-btn primary">Save UI Preview</button></div></form>`;
 const m=modal(modalTitle,r.name||'Financial terms',body,'','ac10-large-modal ac10-agent-preview');m.$('[data-close]').onclick=m.close;
 m.$('[data-agent-terms-form]').onsubmit=event=>{event.preventDefault();const v=G.formVal(event.currentTarget);if(!v.name.trim()||!v.phone.trim())return G.toast('Enter agent name and phone','bad');if(n(v.commission_pct)>100||n(v.commission_pct)<0)return G.toast('Commission must be 0–100%','bad');
 if(isNew){s.channels.agents.push({...r,...v,channel_key:'agent:preview-'+Date.now(),__preview:true});idx=s.channels.agents.length-1;}s.localAgentTerms??={};s.localAgentTerms[idx]=v;
 if(root?.isConnected){root.querySelector('[data-agent-list]').innerHTML=renderAgents(s);root.querySelectorAll('[data-ac10="agent-tab"]').forEach(b=>{if(b.dataset.value==='agents')b.textContent='Agent Configurations '+s.channels.agents.length})}
 m.close();G.toast('Preview updated locally — backend save not available','ok');};
}
function agentEdit(s,idx){const c=s.configs[idx];if(!c)return;const input=(label,name,value,type='text')=>field(label,name,value,type,'required');const m=modal('Edit '+(c.ota_display_name||c.ota_slug),'OTA financial configuration',`<form data-otaform><div class="ac10-grid-4">${input('Operator code','ota_slug',c.ota_slug)}${input('Commission %','commission_percent',c.commission_percent,'number')}${`<label class="ac10-field"><span>Commission base</span>${sel('commission_base',[['fare_only','Fare Only'],['fare_plus_gst','Fare + GST']],c.commission_base)}</label>`}${input('Tax on fare %','tax_on_fare_percent',c.tax_on_fare_percent??0,'number')}${input('GST on commission %','gst_on_commission_percent',c.gst_on_commission_percent??18,'number')}${input('TDS %','tds_percent',c.tds_percent??0,'number')}${input('Cycle (days)','settlement_cycle_days',c.settlement_cycle_days??7,'number')}${`<label class="ac10-field"><span>Settlement mode</span>${sel('settlement_mode',[['DOJ','DOJ (Date of Journey)'],['DOB','DOB (Date of Booking)']],c.settlement_mode)}</label>`}${input('TDS section','tds_section',c.tds_section||'194-O on the sale (fare - offer)')}${input('Match tolerance (INR)','match_tolerance',c.match_tolerance??1,'number')}${`<label class="ac10-field"><span>Tax receivable from OTA</span>${sel('tax_receivable_from_ota',[['true','Yes'],['false','No']],String(!!c.tax_receivable_from_ota))}</label>`}${`<label class="ac10-field"><span>Commission kept on passenger cancel</span>${sel('commission_kept_on_passenger_cancel',[['true','Yes'],['false','No']],String(!!c.commission_kept_on_passenger_cancel))}</label>`}</div><label class="ac10-checkbox"><input type="checkbox" name="is_active" ${c.is_active?'checked':''}> Active</label><div class="ac10-modalbuttons"><button type="button" class="ac10-btn subtle" data-close>Cancel</button><button type="submit" class="ac10-btn primary">Save</button></div></form>`,'','ac10-large-modal');m.$('[data-close]').onclick=m.close;m.$('[data-otaform]').onsubmit=async evt=>{evt.preventDefault();const vals=G.formVal(evt.currentTarget);const next={...c,...vals,tax_receivable_from_ota:String(vals.tax_receivable_from_ota)==='true',commission_kept_on_passenger_cancel:String(vals.commission_kept_on_passenger_cancel)==='true'};if(!Number.isFinite(Number(next.commission_percent))||n(next.commission_percent)<0)return G.toast('Invalid commission','bad');try{await G.put('/reconciliation/config',s.configs.map((x,j)=>j===idx?next:x));m.close();G.toast('OTA configuration saved','ok');window.dispatchEvent(new Event('hashchange'))}catch(err){G.err(err)}};}
function agentAdd(s){if(s.agentTab==='agents'){G.toast('Agent creation is managed in Team & Access; this API is read-only here.','bad');return}G.prompt('Add OTA configuration',[{name:'ota_slug',label:'OTA code',required:true},{name:'ota_display_name',label:'Display name',required:true},{name:'commission_percent',label:'Commission %',type:'number',value:0},{name:'settlement_cycle_days',label:'Settlement days',type:'number',value:7}],{ok:'Add OTA'}).then(async v=>{if(!v)return;try{if(s.configs.some(x=>x.ota_slug===v.ota_slug))return G.toast('OTA exists','bad');await G.put('/reconciliation/config',[...s.configs,{...v,commission_base:'fare_only',settlement_mode:'DOJ',tds_percent:0.1,gst_on_commission_percent:18,is_active:true}]);window.dispatchEvent(new Event('hashchange'))}catch(err){G.err(err)}})}
async function loyalty(root,s){const d=await api('/coupons');s.coupons=a(d.coupons);const rows=s.coupons;root.innerHTML=`<div class="ac10-row-between ac10-reporttitle"><div><h2><span class="ac10-badgeicon">${ic('loyalty')}</span> Loyalty Coupons</h2><p>Operator-scoped catalogue. Codes here are validated server-side at booking time.</p></div>${btn(`${ic('plus',17)} New Coupon`,'coupon-new','primary purple')}</div><div class="ac10-section ac10-coupontable">${table(rows,[{key:'code',label:'CODE'},{key:'discount_value',label:'DISCOUNT'},{key:'audience',label:'AUDIENCE'},{key:'channels',label:'CHANNELS'},{key:'min_fare',label:'MIN FARE',type:'money'},{key:'max_discount_amount',label:'CAP',type:'money'},{key:'per_user_limit',label:'LIMITS'},{key:'valid_until',label:'VALIDITY'},{key:'uses_30d',label:'USED (30D)',type:'int'},{key:'is_active',label:'STATUS'},{key:'action',label:'ACTIONS'}],{cell:(r,c,idx)=>c.key==='discount_value'?`<span class="ac10-type ok">${r.discount_type==='percent'?n(r.discount_value)+'% off':money(r.discount_value)+' flat'}</span>`:c.key==='channels'?e(a(r.channels).join(', ')||'All channels'):c.key==='is_active'?`<span class="ac10-status ${r.is_active?'ok':'bad'}">${r.is_active?'Active':'Inactive'}</span>`:c.key==='action'?`${btn(`${ic('edit',12)} Edit`,'coupon-edit','light',`data-index="${idx}"`)} ${btn(r.is_active?'Deactivate':'Activate','coupon-toggle',r.is_active?'danger':'green',`data-index="${idx}"`)}`:fmt(r[c.key],c.type)})}</div>`;}
function couponDialog(s,idx){const c=idx===null?{code:'',description:'',discount_type:'flat',discount_value:'',audience:'all',channels:['website','agent','branch'],stackable:false,is_active:true,valid_from:'',valid_until:''}:s.coupons[idx];if(!c)return;const isNew=idx===null;const m=modal(isNew?'New Coupon':'Edit '+c.code,'Update this discount code',`<form data-coupon-form><div class="ac10-grid-2">${field('Code*','code',c.code,'text',isNew?'required pattern="[A-Za-z0-9]{3,20}"':'readonly')}${field('Description','description',c.description)}<label class="ac10-field"><span>Type*</span>${sel('discount_type',[['flat','Flat ₹'],['percent','Percent %']],c.discount_type)}</label>${field('Value*','discount_value',c.discount_value,'number','required min="0" step="0.01"')}${field('Min fare (₹)','min_fare',c.min_fare??'','number','min="0"')}${field('Max ₹ off (n/a)','max_discount_amount',c.max_discount_amount??'','number','min="0"')}${field('Total redemptions','total_limit',c.total_limit??'','number','min="0"')}${field('Per-user limit','per_user_limit',c.per_user_limit??'','number','min="0"')}${field('Valid from','valid_from',c.valid_from??'','date')}${field('Valid until','valid_until',c.valid_until??'','date')}</div><label class="ac10-field"><span>Audience</span>${sel('audience',[['all','Anyone'],['new','New customers'],['repeat','Repeat customers']],c.audience)}</label><div class="ac10-couponchannels"><b>Channels</b><div>${[['website','Website'],['agent','Agent'],['branch','Branch']].map(([key,name])=>`<label class="ac10-checkbox"><input type="checkbox" name="channel_${key}" ${a(c.channels).includes(key)?'checked':''}> ${e(name)}<small>Available to ${e(name)} bookings</small></label>`).join('')}</div></div><div class="ac10-couponflags"><label class="ac10-checkbox"><input name="private" type="checkbox" ${c.private?'checked':''}> Private</label><label class="ac10-checkbox"><input name="stackable" type="checkbox" ${c.stackable?'checked':''}> Stackable with other discounts (miles, manual)</label><label class="ac10-checkbox"><input name="is_active" type="checkbox" ${c.is_active?'checked':''}> Active</label></div><div class="ac10-modalbuttons"><button type="button" class="ac10-btn subtle" data-close>Cancel</button><button type="submit" class="ac10-btn primary">${isNew?'Create coupon':'Save changes'}</button></div></form>`,'','ac10-coupon-modal');m.$('[data-close]').onclick=m.close;m.$('[data-coupon-form]').onsubmit=async evt=>{evt.preventDefault();const v=G.formVal(evt.currentTarget);if(!(n(v.discount_value)>0))return G.toast('Discount must be positive','bad');if(v.valid_from&&v.valid_until&&v.valid_from>v.valid_until)return G.toast('Invalid date range','bad');const next={...v,code:String(v.code).toUpperCase(),channels:['website','agent','branch'].filter(x=>v['channel_'+x]),valid_from:v.valid_from||null,valid_until:v.valid_until||null};for(const key of ['website','agent','branch'])delete next['channel_'+key];try{if(isNew)await G.post('/coupons',next);else await G.put('/coupons/'+c.id,next);m.close();G.toast('Coupon saved','ok');window.dispatchEvent(new Event('hashchange'))}catch(err){G.err(err)}};}
async function runAction(root,s,b,evt){const op=b.dataset.ac10;if(['change-basis','change-pivot','transaction-kind','receivables-kind','report-toggle','recon-kind','agent-tab'].includes(op))return;
 try{switch(op){case 'print':window.print();break;case 'export':{
  const path=s.tab==='transactions'?'/accounts/transactions':s.tab==='receivables'?'/accounts/receivables':s.tab==='reports'&&s.id?'/accounts/reports/'+s.id:null;
  if(path){await G.download(path+'?'+G.qs({from:s.from,to:s.to,format:'csv',source:s.source||undefined}),`${s.tab}_${s.id||''}_${s.from}_${s.to}.csv`);}else{const rows=s.rows||[];if(!rows.length)G.toast('No exportable rows','bad');else{const columns=Object.keys(rows[0]);const csv=[columns,...rows.map(r=>columns.map(k=>r[k]==null?'':String(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])))].map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));link.download=`accounts_${s.tab}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1500)}}break;}case 'share':navigator.clipboard?.writeText(location.href).then(()=>G.toast('Report link copied','ok')).catch(()=>G.toast('Copy the URL from your browser'));break;
  case 'refresh':window.dispatchEvent(new Event('hashchange'));break;
  case 'preset':{const which=b.dataset.preset;let from=addDays(today(),-6),to=today();if(which==='month')from=today().slice(0,7)+'-01';if(which==='last'){const d=new Date(today()+'T12:00:00');d.setDate(0);to=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');from=to.slice(0,7)+'-01'}root.querySelectorAll('[name=from]').forEach(x=>x.value=from);root.querySelectorAll('[name=to]').forEach(x=>x.value=to);break;}
  case 'report-apply':{const from=root.querySelector('[name=from]')?.value||s.from,to=root.querySelector('[name=to]')?.value||s.to;if(from>to)return G.toast('Invalid date range','bad');queryUpdated(s,{from,to});break;}
  case 'filter-apply':{const f=root.querySelector('[data-filters]');if(!f)return;const q=normalizeForm(f);if(q.from>q.to)return G.toast('Invalid date range','bad');queryUpdated(s,q);break;}
  case 'ledger-open':await ledgerDialog(b.dataset.channel,b.dataset.ledtype||'credit');break;
  case 'invoice-pay':await invoicePay(s.invoiceData);break;
  case 'invoice-view':{const r=s.invoiceData.documents.find(x=>String(x.id)===b.dataset.doc);if(r)invoiceView(r);break;}
  case 'invoice-pdf':case 'invoice-download':G.toast('Original provider PDF not available through the connected API. Use View for a printable summary.','bad');break;
  case 'invoice-statement':case 'statement':G.toast('Statements are listed by month below','ok');break;
  case 'reconcile-toggle':{const area=root.querySelector('[data-ac10-uploadarea]');if(area)area.hidden=!area.hidden;break;}
  case 'reconcile-upload':{const f=root.querySelector('[data-ota-file]')?.files?.[0];const ota=root.querySelector('[name=ota]')?.value;if(!f||!ota)return G.toast('Select OTA and CSV file','bad');if(!/\.csv$/i.test(f.name))return G.toast('Only CSV is accepted by the current reconciliation API','bad');const csv=await f.text();const d=await G.post('/reconciliation/settlements',{ota_slug:ota,file_name:f.name,csv});location.hash='#/accounts/reconciliation/'+d.id;break;}
  case 'agent-edit':if(s.agentTab==='otas')agentEdit(s,Number(b.dataset.index));else agentTermsDialog(s,Number(b.dataset.index),root);break;
  case 'agent-view':{const r=s.channels.agents[Number(b.dataset.index)];await ledgerDialog(r.channel_key);break;}
  case 'agent-add':if(s.agentTab==='agents')agentTermsDialog(s,null,root);else agentAdd(s);break;
  case 'agent-toggle':case 'agent-delete':{const idx=Number(b.dataset.index);const r=s.configs[idx];if(!r)return;if(op==='agent-delete'&&!await G.confirm(`Delete configuration ${e(r.ota_display_name||r.ota_slug)}?`,{ok:'Delete',danger:true}))return;const all=op==='agent-delete'?s.configs.filter((_,i)=>i!==idx):s.configs.map((c,i)=>i===idx?{...c,is_active:!c.is_active}:c);await G.put('/reconciliation/config',all);G.toast('Configuration updated','ok');window.dispatchEvent(new Event('hashchange'));break;}
  case 'coupon-new':couponDialog(s,null);break;case 'coupon-edit':couponDialog(s,Number(b.dataset.index));break;
  case 'coupon-toggle':{const c=s.coupons[Number(b.dataset.index)];if(!c)return;if(!await G.confirm(`${c.is_active?'Deactivate':'Activate'} coupon ${e(c.code)}?`,{ok:'Confirm'}))return;await G.put('/coupons/'+c.id,{is_active:!c.is_active});G.toast('Coupon updated','ok');window.dispatchEvent(new Event('hashchange'));break;}
  default:break;
 }}catch(err){G.err(err)}}
G.screens.accounts=async function(el,p={}){
 const tab=p.tab||'analytics';const id=p.id||null;const q=G.query();const s={tab,id,q,...dateDefault(),basis:q.basis||'travel_date',pivot:q.pivot||'date',source:q.source||'all',sector:q.sector||'all',service:q.service||'all',kind:q.kind||'all',search:q.q||'',type:'all'};
 el.classList.add('ac10-root');el.innerHTML=topNav(tab)+'<section class="ac10-content" data-ac10-page><div class="ac10-loading">Loading Accounts…</div></section>';const root=el.querySelector('[data-ac10-page]');
 const fn={analytics:sales,transactions,receivables,reports,invoices,reconciliation,'agent-settings':agentSettings,coupons:loyalty}[tab];if(!fn){await previous(el,p);return}
 if((tab==='reports'&&!can('accounts.reports'))||(tab==='reconciliation'&&!can('accounts.reconciliation'))||(tab==='coupons'&&!can('offers.manage_coupons'))||(tab==='receivables'&&!can('accounts.ledger')))return root.innerHTML=empty('You do not have permission to view this module');
 try{if(tab==='reports'&&id==='staff-duty'){const st=await api('/staff').catch(()=>null);s.staffList=a(st?.staff||st?.rows||st)}await fn(root,s)}catch(err){root.innerHTML=`<div class="ac10-empty error">${ic('reports',30)}<b>Could not load ${e(tab)}</b><p>${e(err.message)}</p></div>`;G.err(err)}
 root.addEventListener('click',ev=>{const b=ev.target.closest('[data-ac10]');if(b&&root.contains(b))runAction(root,s,b,ev)});
 root.addEventListener('change',ev=>{const t=ev.target;if(t.matches('input[name=from],input[name=to],select[name=source],select[name=sector],select[name=service]')&&!t.closest('[data-filters]')){const data={from:root.querySelector('[name=from]')?.value||s.from,to:root.querySelector('[name=to]')?.value||s.to,source:root.querySelector('select[name=source]')?.value||s.source,pivot:s.pivot,basis:s.basis};if(data.from>data.to)return G.toast('Invalid date range','bad');if(s.tab==='analytics'||s.tab==='transactions')queryUpdated(s,data)}});
};
})();
